#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){int n=stoi(argv[1]); int m=n*(n-1)/2;vector<pair<int,int>> edges;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)edges.emplace_back(i,j);vector<uint32_t> neigh(m);for(int i=0;i<m;i++)for(int j=0;j<m;j++)if(i!=j&&(edges[i].first==edges[j].first||edges[i].first==edges[j].second||edges[i].second==edges[j].first||edges[i].second==edges[j].second))neigh[i]|=1u<<j; int threshold=n-2;int N=1;for(int i=0;i<m;i++)N*=3;vector<int> nxt(N),outdeg(m);for(int x=0;x<N;x++){int a=x;uint32_t mask=0;int pow3=1;vector<int> vals(m);for(int i=0;i<m;i++){vals[i]=a%3;a/=3;if(vals[i]==1) mask|=1u<<i;}int y=0;for(int i=0;i<m;i++){int z=vals[i]==1?2:(vals[i]==2?0:(__builtin_popcount(mask &neigh[i])>=threshold?1:0));y+=z*pow3;pow3*=3;}nxt[x]=y;}vector<uint8_t> color(N,0);vector<int> depth(N,-1), cyc_len(N,0);int cycles=0,nonzero=0,maxdepth=0;map<int,int> pcount;for(int i=0;i<N;i++)if(color[i]==0){vector<int>path;int v=i;while(color[v]==0){color[v]=1;path.push_back(v);v=nxt[v];}if(color[v]==1){int j=find(path.begin(),path.end(),v)-path.begin();int p=path.size()-j;cycles++;pcount[p]++;nonzero+=(p>1);for(int k=j;k<(int)path.size();k++){depth[path[k]]=0;cyc_len[path[k]]=p;}}for(int k=(int)path.size()-1;k>=0;k--){int u=path[k];if(depth[u]<0){depth[u]=depth[nxt[u]]+1;cyc_len[u]=cyc_len[nxt[u]];}maxdepth=max(maxdepth,depth[u]);color[u]=2;}}cout<<"n="<<n<<" N="<<N<<" cycles="<<cycles<<" nontrivial="<<nonzero<<" maxdepth="<<maxdepth<<" periods:";for(auto [p,c]:pcount)cout<<" ("<<p<<","<<c<<")";cout<<"\n";}
